    plOrder: [], // the settings' platform order, shown or not; prov follows it
    crTracks: true,
    byName: false, plNames: false, plHover: false, plSize: 22, dis: 'below', width: 1280,
    on: true,
    thumbs: true,
    extras: ['rating', 'tags'],
    facts: ['released', 'labels', 'barcode', 'length', 'links'],
