/* ── hero ──────────────────────────────────────────── */
const FACTS = [['released', 'Released'], ['labels', 'Labels'], ['barcode', 'Barcode'], ['length', 'Length'], ['mbid', 'MBID'], ['asin', 'ASIN'], ['packaging', 'Packaging'], ['lang', 'Language / script'], ['quality', 'Data quality'], ['links', 'Release links']];
